            },
          }),
          {
            headers: {
              'Content-Type': 'application/octet-stream',
              'Content-Length': '3',
            },
          },
        ),
  );
  const pending = f.selectFile();
  const request = await flushFileRequest(f);
  f.answer(request, {
    status: 'selected',
    selection: selectedFor(request.selection.selection_id),
